export const blotch = (colors, shares, W, H, seed, scale) => {
  const A = BLOTCH_ART;
  // The artwork is a full tessellation (55 cells cover the board). Every
  // colour, base included, is dealt cells by share with a greedy balance so
  // each gets a mix of large and small cells. Cells cut by the board edge are
  // The base colour is the ground under the tile.
  // One tile covers the surface (the artwork is not a seamless repeat).
  // scale > 1 zooms in; the seed also pans so reshuffles show new areas.
  // Size by the shorter side (so a long thin part gets cells in proportion),
  // then repeat the tile only if the long side needs it.
  // The artwork is not a seamless repeat, so one tile covers the surface.
  // PATCH SIZE zooms in from cover (never out, which would expose a seam).
  const sc = Math.max(W / A.W, H / A.H) * Math.max(1, scale || 1);
  const tw = A.W * sc, th = A.H * sc;
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  if (colors.length < 2) return s;
  const rnd = mkRnd((seed || 0) + 11);
  const n = colors.length;
  const shTot = shares.reduce((acc, v) => acc + v, 0) || 1;
  // shuffle cell order per seed, then sort by area desc with light jitter so
  // the deal changes between seeds
  const cells = A.paths.slice().sort((p, q) => (q.a * (0.8 + rnd() * 0.4)) - (p.a * (0.8 + rnd() * 0.4)));
  const tot = cells.reduce((acc, p) => acc + p.a, 0);
  const got = colors.map(() => 0);
  const groups = colors.map(() => '');
  cells.forEach((p) => {
    let best = 0, bestGap = -Infinity;
    for (let i = 0; i < n; i++) {
      const gap = (shares[i] / shTot) - (got[i] / tot) + (rnd() - 0.5) * 0.03;
      if (gap > bestGap) { bestGap = gap; best = i; }
    }
    got[best] += p.a;
    let g = '<path d="' + p.d + '"/>';
    groups[best] += g;
  });
  const tileId = 'blotch-' + (seed || 0) + '-' + Math.round(sc * 1000) + '-' + colors.join('').replace(/#/g, '');
  let tile = '';
  for (let c = 0; c < n; c++) if (c !== 0) tile += '<g fill="' + colors[c] + '" stroke="' + colors[c] + '" stroke-width="1.5">' + groups[c] + '</g>';
  s += '<defs><g id="' + tileId + '">' + tile + '</g></defs>';
  // seed also pans within the slack so reshuffles show a different crop
  const ox0 = (W - tw) * rnd(), oy0 = (H - th) * rnd();
  s += '<use href="#' + tileId + '" transform="translate(' + F(ox0) + ' ' + F(oy0) + ') scale(' + (Math.round(sc * 10000) / 10000) + ')"/>';
  return s;
};

// Digital: a coarse block grid; a layered sine field is quantised so each
// colour owns a band of the field equal to its share. Blocks merge into
// stepped 90° patches.
export const digital = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed);
  const cell = Math.max(4, Math.sqrt(W * H) * 0.028 * (scale || 1));
  const nx = Math.ceil(W / cell), ny = Math.ceil(H / cell);
  const ph = [rnd() * 6.283, rnd() * 6.283, rnd() * 6.283, rnd() * 6.283];
  const k = [2 + rnd() * 2, 2 + rnd() * 2, 3 + rnd() * 3, 3 + rnd() * 3];
  const vals = new Float32Array(nx * ny);
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    // quantise the sample position to 2×2 macro cells for a blockier read
    const a = (Math.floor(i / 2) * 2 / nx) * 6.283, b = (Math.floor(j / 2) * 2 / ny) * 6.283;
    let v = Math.sin(a * k[0] + ph[0]) + Math.sin(b * k[1] + ph[1]) + 0.8 * Math.sin(a * k[2] + b * 0.7 + ph[2]) + 0.6 * Math.sin(a * 0.5 - b * k[3] + ph[3]);
    v += (rnd() - 0.5) * 0.9; // grain
    vals[j * nx + i] = v;
  }
  // thresholds by quantile so shares hold
  const sorted = Array.from(vals).sort((a, b) => a - b);
  const cuts = []; let acc = 0;
  for (let i = 0; i < colors.length - 1; i++) { acc += shares[i]; cuts.push(sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * acc / 100))]); }
  const idxOf = (v) => { let i = 0; while (i < cuts.length && v > cuts[i]) i++; return i; };
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  const groups = colors.map(() => '');
  for (let j = 0; j < ny; j++) {
    let i = 0;
    while (i < nx) {
      const ci = idxOf(vals[j * nx + i]);
      let run = 1;
      while (i + run < nx && idxOf(vals[j * nx + i + run]) === ci) run++;
      if (ci !== 0) groups[ci] += '<rect x="' + F(i * cell) + '" y="' + F(j * cell) + '" width="' + F(run * cell + 0.3) + '" height="' + F(cell + 0.3) + '"/>';
      i += run;
    }
  }
  for (let c = 1; c < colors.length; c++) s += '<g fill="' + colors[c] + '">' + groups[c] + '</g>';
  return s;
};

// Proportional stripes: vertical bands, widths = shares.
export const stripes = (colors, shares, W, H) => {
  let s = '', x = 0;
  colors.forEach((c, i) => { const w = W * shares[i] / 100; s += '<rect x="' + F(x) + '" y="0" width="' + F(w + 0.5) + '" height="' + H + '" fill="' + c + '"/>'; x += w; });
  return s;
};


// Tiger stripe: horizontal brush strokes with ragged ends, layered by share.
export const tiger = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed + 3);
  const sc = scale || 1;
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  const h0 = H * 0.045 * sc;
  for (let i = 1; i < colors.length; i++) {
    const count = Math.max(4, Math.round((shares[i] / 100) * (H / h0) * 2.0));
    let g = '<g fill="' + colors[i] + '">';
    for (let k = 0; k < count; k++) {
      const y = rnd() * H, x0 = -W * 0.15 + rnd() * W * 0.6, len = W * (0.3 + rnd() * 0.6), th = h0 * (0.5 + rnd() * 0.9);
      const tilt = (rnd() - 0.5) * H * 0.08;
      let d = 'M' + F(x0) + ' ' + F(y);
      const segs = 12;
      for (let j = 1; j <= segs; j++) { const t = j / segs; d += ' L' + F(x0 + len * t) + ' ' + F(y + tilt * t + (rnd() - 0.5) * th * 0.35 - th * Math.sin(t * Math.PI) * 0.5); }
      for (let j = segs; j >= 0; j--) { const t = j / segs; d += ' L' + F(x0 + len * t) + ' ' + F(y + tilt * t + (rnd() - 0.5) * th * 0.35 + th * Math.sin(t * Math.PI) * 0.5 + th * 0.15); }
      g += '<path d="' + d + 'Z"/>';
    }
    s += g + '</g>';
  }
  return s;
};

// Splinter: angular shards from a jittered triangle lattice, coloured by share.
export const splinter = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed + 5);
  const cell = Math.sqrt(W * H) * 0.09 * (scale || 1);
  const nx = Math.ceil(W / cell) + 2, ny = Math.ceil(H / cell) + 2;
  const pts = [];
  for (let j = 0; j <= ny; j++) { pts.push([]); for (let i = 0; i <= nx; i++) pts[j].push([(i - 1) * cell + (rnd() - 0.5) * cell * 0.9, (j - 1) * cell + (rnd() - 0.5) * cell * 0.9]); }
  const tris = [];
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const a = pts[j][i], b = pts[j][i + 1], c = pts[j + 1][i], d = pts[j + 1][i + 1];
    if (rnd() > 0.5) { tris.push([a, b, d]); tris.push([a, d, c]); } else { tris.push([a, b, c]); tris.push([b, d, c]); }
  }
  // weight: pick colour per tri by share, with a bias to stick with a neighbour so shards cluster
  const groups = colors.map(() => '');
  const cum = []; let acc = 0; shares.forEach((v) => { acc += v; cum.push(acc); });
  let last = 0;
  tris.forEach((t) => {
    let c = last;
    if (rnd() > 0.45) { const v = rnd() * 100; c = cum.findIndex((x) => v <= x); if (c < 0) c = colors.length - 1; }
    last = c;
    groups[c] += '<polygon points="' + t.map((p) => F(p[0]) + ',' + F(p[1])).join(' ') + '"/>';
  });
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  for (let c = 1; c < colors.length; c++) s += '<g fill="' + colors[c] + '" stroke="' + colors[c] + '" stroke-width="0.6">' + groups[c] + '</g>';
  return s;
};

// Hex: honeycomb cells, coloured by a smooth field quantised to the shares.
export const hex = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed + 7);
  const r0 = Math.sqrt(W * H) * 0.028 * (scale || 1);
  const w = r0 * Math.sqrt(3), h = r0 * 1.5;
  const ph = [rnd() * 6.3, rnd() * 6.3, rnd() * 6.3];
  const cells = [];
  for (let j = -1; j * h < H + h; j++) for (let i = -1; i * w < W + w; i++) {
    const cx = i * w + (j % 2 ? w / 2 : 0), cy = j * h;
    const v = Math.sin(cx / W * 7 + ph[0]) + Math.sin(cy / H * 5 + ph[1]) + 0.7 * Math.sin((cx + cy) / (W + H) * 11 + ph[2]) + (rnd() - 0.5) * 1.1;
    cells.push({ cx, cy, v });
  }
  const sorted = cells.map((c) => c.v).sort((a, b) => a - b);
  const cuts = []; let acc = 0;
  for (let i = 0; i < colors.length - 1; i++) { acc += shares[i]; cuts.push(sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * acc / 100))]); }
  const hexPts = (cx, cy) => { let p = ''; for (let k = 0; k < 6; k++) { const a = Math.PI / 6 + k * Math.PI / 3; p += F(cx + r0 * 0.97 * Math.cos(a)) + ',' + F(cy + r0 * 0.97 * Math.sin(a)) + ' '; } return p; };
  const groups = colors.map(() => '');
  cells.forEach((c) => { let i = 0; while (i < cuts.length && c.v > cuts[i]) i++; groups[i] += '<polygon points="' + hexPts(c.cx, c.cy) + '"/>'; });
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  for (let c = 0; c < colors.length; c++) s += '<g fill="' + colors[c] + '">' + groups[c] + '</g>';
  return s;
};

// Topographic: contour bands of a smooth height field, quantised to the shares,
// drawn as a raster of thin horizontal runs so the bands read as closed contours.
export const topo = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed + 9);
  const sc = scale || 1;
  const step = Math.max(2, Math.sqrt(W * H) / 180);
  const nx = Math.ceil(W / step), ny = Math.ceil(H / step);
  const peaks = []; for (let k = 0; k < 7; k++) peaks.push([rnd() * W, rnd() * H, (0.6 + rnd()) * Math.min(W, H) * 0.35 * sc, rnd() > 0.3 ? 1 : -1]);
  const field = new Float32Array(nx * ny);
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const x = i * step, y = j * step; let v = 0;
    peaks.forEach((p) => { const d2 = ((x - p[0]) ** 2 + (y - p[1]) ** 2) / (p[2] * p[2]); v += p[3] * Math.exp(-d2); });
    field[j * nx + i] = v;
  }
  // repeating bands: wrap the field so every colour recurs like contour lines
  const bands = colors.length;
  const cycles = 2.2;
  const mn = Math.min.apply(null, field), mx = Math.max.apply(null, field);
  const cum = []; let acc = 0; shares.forEach((v) => { acc += v / 100; cum.push(acc); });
  const idxOf = (v) => { const t = (((v - mn) / (mx - mn || 1)) * cycles) % 1; let i = 0; while (i < bands - 1 && t > cum[i]) i++; return i; };
  const groups = colors.map(() => '');
  for (let j = 0; j < ny; j++) { let i = 0; while (i < nx) { const c = idxOf(field[j * nx + i]); let run = 1; while (i + run < nx && idxOf(field[j * nx + i + run]) === c) run++; if (c !== 0) groups[c] += '<rect x="' + F(i * step) + '" y="' + F(j * step) + '" width="' + F(run * step + 0.4) + '" height="' + F(step + 0.4) + '"/>'; i += run; } }
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  for (let c = 1; c < colors.length; c++) s += '<g fill="' + colors[c] + '">' + groups[c] + '</g>';
  return s;
};

// Star: the KLEEQ star motif scattered at three sizes over the base; stars
// are dealt to the layer colours by share.
const starPath = (cx, cy, r, rot) => { let d = ''; for (let k = 0; k < 10; k++) { const a = rot + k * Math.PI / 5; const rr = k % 2 ? r * 0.42 : r; d += (k ? 'L' : 'M') + F(cx + rr * Math.cos(a)) + ' ' + F(cy + rr * Math.sin(a)); } return d + 'Z'; };
export const star = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed + 13);
  const r0 = Math.sqrt(W * H) * 0.05 * (scale || 1);
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  const layer = colors.slice(1), ls = shares.slice(1);
  const lsTot = ls.reduce((a, b) => a + b, 0) || 1;
  const total = Math.round((W * H) / (r0 * r0 * 2.2));
  const groups = layer.map(() => '');
  for (let k = 0; k < total; k++) {
    const v = rnd() * lsTot; let acc = 0, c = 0; for (; c < ls.length; c++) { acc += ls[c]; if (v <= acc) break; } if (c >= ls.length) c = ls.length - 1;
    const r = r0 * (0.35 + rnd() * rnd() * 1.3);
    groups[c] += '<path d="' + starPath(rnd() * W, rnd() * H, r, rnd() * 6.3) + '"/>';
  }
  for (let c = 0; c < layer.length; c++) s += '<g fill="' + layer[c] + '">' + groups[c] + '</g>';
  return s;
};

// Fade: each colour dissolves into the next left to right with a dither of
// small squares; share sets each band's width.
export const fade = (colors, shares, W, H, seed, scale) => {
  const rnd = mkRnd(seed + 17);
  const cell = Math.max(3, Math.sqrt(W * H) * 0.012 * (scale || 1));
  let s = '<rect width="' + W + '" height="' + H + '" fill="' + colors[0] + '"/>';
  const bounds = []; let x = 0; shares.forEach((v) => { bounds.push([x, x + W * v / 100]); x += W * v / 100; });
  const groups = colors.map(() => '');
  const nx = Math.ceil(W / cell), ny = Math.ceil(H / cell);
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const px = (i + 0.5) * cell;
    let c = bounds.findIndex((b) => px >= b[0] && px < b[1]); if (c < 0) c = colors.length - 1;
    // near a boundary, flip to the neighbour with probability by distance
    const b = bounds[c]; const span = (b[1] - b[0]) || 1;
    const tR = (px - b[0]) / span, tL = (b[1] - px) / span;
    if (c < colors.length - 1 && tR > 0.5 && rnd() < (tR - 0.5) * 1.6) c++;
    else if (c > 0 && tL > 0.5 && rnd() < (tL - 0.5) * 1.6) c--;
    if (c !== 0) groups[c] += '<rect x="' + F(i * cell) + '" y="' + F(j * cell) + '" width="' + F(cell + 0.3) + '" height="' + F(cell + 0.3) + '"/>';
  }
  for (let c = 1; c < colors.length; c++) s += '<g fill="' + colors[c] + '">' + groups[c] + '</g>';
  return s;
};

export const PATTERNS = [
  { id: 'blotch', label: 'Blotch' }, { id: 'digital', label: 'Digital' }, { id: 'stripes', label: 'Stripes' },
  { id: 'tiger', label: 'Tiger' }, { id: 'splinter', label: 'Splinter' }, { id: 'hex', label: 'Hex' },
  { id: 'topo', label: 'Topo' }, { id: 'star', label: 'Star' }, { id: 'fade', label: 'Fade' }
];
const RENDERERS = { blotch, digital, stripes, tiger, splinter, hex, topo, star, fade };

// Sheen: a soft highlight pass whose strength follows Cerakote's published
// gloss word. Returns 0 (flat) .. 1 (high gloss); null when unpublished.
const GLOSS_LEVEL = { flat: 0, matte: 0.15, eggshell: 0.3, satin: 0.45, 'semi gloss': 0.65, 'semi-gloss': 0.65, gloss: 0.85, 'high gloss': 1 };
export const glossLevel = (word) => { const k = String(word || '').trim().toLowerCase(); return k in GLOSS_LEVEL ? GLOSS_LEVEL[k] : null; };
export const sheenOverlay = (W, H, level, id) => {
  if (!level) return '';
  const a = 0.08 + level * 0.3;
  return '<defs><linearGradient id="' + id + '" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="' + F(a) + '"/><stop offset="0.42" stop-color="#fff" stop-opacity="' + F(a * 0.15) + '"/><stop offset="0.6" stop-color="#fff" stop-opacity="' + F(a * 0.7) + '"/><stop offset="1" stop-color="#000" stop-opacity="' + F(level * 0.18) + '"/></linearGradient></defs>'
    + '<rect width="' + W + '" height="' + H + '" fill="url(#' + id + ')"/>';
};

// Nearest finishes to a list of RGB hexes (for colours lifted from a photo).
const dist2 = (a, b) => { const A = rgb(a), B = rgb(b); return (A[0] - B[0]) ** 2 + (A[1] - B[1]) ** 2 + (A[2] - B[2]) ** 2; };
export const nearestFinishes = (hexes, pool, n) => {
  const used = {}; const out = [];
  hexes.forEach((h) => {
    let best = null, bd = Infinity;
    pool.forEach((f) => { if (used[f.code]) return; const d = dist2(h, f.hex) + (f.wall === 'core' ? 300 : 0); if (d < bd) { bd = d; best = f; } });
    if (best) { used[best.code] = 1; out.push(best); }
  });
  return out.slice(0, n || hexes.length);
};

export const render = (kind, colors, shares, W, H, seed, scale) => (RENDERERS[kind] || blotch)(colors, shares, W, H, seed, scale);

